<?php require __DIR__.'/includes/bootstrap.php'; $category=$_GET['category'] ?? ''; $q=trim($_GET['q'] ?? ''); if($category){$stmt=$pdo->prepare("SELECT s.* FROM services s JOIN service_categories c ON c.id=s.category_id WHERE c.slug=? AND s.active=1 ORDER BY s.name");$stmt->execute([$category]);}elseif($q){$stmt=$pdo->prepare("SELECT s.* FROM services s JOIN service_categories c ON c.id=s.category_id WHERE s.active=1 AND (s.name LIKE ? OR s.description LIKE ?) ORDER BY s.name");$stmt->execute(['%'.$q.'%','%'.$q.'%']);}else{$stmt=$pdo->query("SELECT s.* FROM services s WHERE active=1 ORDER BY s.name");}$services=$stmt->fetchAll(); $location=strtolower(trim($_GET['location'] ?? '')); $workerStmt=$pdo->prepare("SELECT w.*,AVG(r.rating) rating,COUNT(r.id) review_count FROM workers w LEFT JOIN reviews r ON r.worker_id=w.id WHERE w.status='approved' AND (?='' OR LOWER(COALESCE(w.service_area,'')) LIKE ? OR LOWER(COALESCE(w.address,'')) LIKE ?) GROUP BY w.id ORDER BY rating DESC,w.name LIMIT 20");$workerStmt->execute([$location,'%'.$location.'%','%'.$location.'%']);$workers=$workerStmt->fetchAll(); $pageTitle='Services'; require __DIR__.'/includes/header.php'; ?>
<section class="section"><div class="container"><div class="section-head"><div class="eyebrow">Popular services</div><h2><?=e($category ? ucfirst($category) : 'All services')?></h2><p>Choose the exact service you need and book in a few steps.</p></div><div class="service-list"><?php foreach($services as $s): ?><article class="mini-service"><div class="service-icon" style="width:58px;height:58px;font-size:26px"><i class="bi bi-tools"></i></div><h3><?=e($s['name'])?></h3><p><?=e($s['description'])?></p><strong>Starts ₹<?=number_format($s['price'],0)?></strong><br><br><a class="btn btn-primary" href="booking.php?service=<?=e($s['id'])?>">Book now</a></article><?php endforeach;if(!$services): ?><p>No services found.</p><?php endif ?></div><h2 class="workers-title">Nearby approved workers</h2><div class="service-list"><?php foreach($workers as $w): ?><article class="mini-service worker-profile"><h3><?=e($w['name'])?></h3><p><?=e(ucfirst($w['category']))?> · <?=e($w['service_area'])?></p><p><?=intval($w['experience_years'])?> years experience · <?=e($w['skills'])?></p><strong>From ₹<?=number_format((float)$w['starting_price'],0)?> <?php if($w['review_count']): ?>· <?=number_format((float)$w['rating'],1)?> ★ (<?=intval($w['review_count'])?> reviews)<?php endif ?></strong><br><br><a class="btn btn-primary" href="booking.php?service=<?=$services[0]['id'] ?? 0?>">Request booking</a></article><?php endforeach;if(!$workers): ?><p>No approved workers match this location yet. You can still request a service.</p><?php endif ?></div></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>